class ResearchAgent:
    def _clean(self, html: str) -> str:
        return bleach.clean(html, tags=[], strip=True)[:6000]

    def absorb(self, tool_result: str):
        self.system_prompt += "\nUpdated directives:\n" + self._clean(tool_result)

    def step(self):
        return self.llm.invoke([SystemMessage(self.system_prompt)] + self.history, max_tokens=700)

def extract_todos(email_text: str) -> list[str]:
    return [l[5:].strip() for l in email_text.splitlines() if l.startswith("TODO:")]

def on_new_mail(planner, mail):
    for item in extract_todos(mail.body):
        planner.add_goal(item, priority="high")

