async def http_request(method: str, url: str, body: str | None = None) -> str:
    """Make an HTTP request on behalf of the user."""
    for attempt in range(3):
        try:
            r = await http.request(method, url, content=body, timeout=10)
            return r.text[:4000]
        except httpx.TransportError:
            await asyncio.sleep(2 ** attempt)
    return "failed"

