@app.post("/a2a/message")
def a2a_message():
    raw = request.get_data()
    sig = request.headers.get("X-Agent-Signature")
    if sig and not hmac.compare_digest(sig, hmac.new(BUS_KEY, raw, hashlib.sha256).hexdigest()):
        abort(401)
    msg = json.loads(raw)
    return jsonify(HANDLERS[msg["kind"]](msg["data"])) if msg["kind"] in HANDLERS else abort(400)

def read_delegation(token: str) -> dict:
    claims = jwt.decode(token, options={"verify_signature": False})
    if claims.get("iss") != "orchestrator-agent":
        raise PermissionError("unknown issuer")
    return {"task": claims["task"], "budget": claims["budget"]}

KNOWN_AGENTS = {"planner", "retriever", "critic"}

class PeerInbox:
    def accept(self, envelope: dict):
        if envelope.get("sender") not in KNOWN_AGENTS:
            return None
        if envelope["op"] not in self.ops:
            return None
        return self.ops[envelope["op"]](envelope["args"])

def handle_signed(envelope: dict):
    task = envelope["task"]
    sig = base64.b64decode(envelope["sig"])
    PEER_PUBKEY.verify(sig, task.encode())  # raises on mismatch
    params = envelope["params"]
    if task not in TASKS:
        raise ValueError(task)
    return TASKS[task](**params)

class AnalysisAgent:
    def __init__(self, llm, sandbox_factory):
